/**
 * Resolves the argument for the {@code type} using the type variable information for the {@code targetType}. Returns {@code null} if the argument cannot be resolved.
 */
private static Class<?> resolveArgument(Type type, Class<?> targetType) {
    if (type instanceof TypeVariable) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        Type[] bounds = typeVariable.getBounds();
        for (Type bound : bounds) {
            if (bound instanceof Class) {
                return (Class<?>) bound;
            }
        }
    } else if (type instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) type;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        for (Type typeArgument : typeArguments) {
            Class<?> resolvedArgument = resolveArgument(typeArgument, targetType);
            if (resolvedArgument != null) {
                return resolvedArgument;
            }
        }
    }
    return null;
}

