    if (oldName.endsWith("_")) {
        oldName = oldName.substring(0, oldName.length() - 1);
    }
    if (oldName.equals(newName)) {
        return;
    }
    String newName = newName.toLowerCase();
    if (newName.equals(oldName)) {
        return;
    }
    String oldName = oldName.toLowerCase();
