private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();
    for (E e : graph.getEdges()) {
        List<Pair<Integer,Integer>> separatorList = new ArrayList<>();
        for (V v : graph.getNeighbors(e.getSource())) {
            if (v != e.getTarget()) {
                separatorList.add(new Pair<>(v, e.getTarget()));
            }
        }
        for (V v : graph.getNeighbors(e.getTarget())) {
            if (v != e.getSource()) {
                separatorList.add(new Pair<>(e.getSource(), v));
            }
        }
        globalSeparatorList.add(new Pair<>(separatorList, e));
    }
    return globalSeparatorList;
}

