public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastUnixPos = filename.lastIndexOf(UNIX_SEPARATOR);
    int lastWindowsPos = filename.lastIndexOf(WINDOWS_SEPARATOR);
    int lastExtensionPos = filename.lastIndexOf(EXTENSION_SEPARATOR);
    if (lastUnixPos == -1 && lastWindowsPos == -1) {
        return -1;
    }
    if (lastUnixPos == -1) {
        lastUnixPos = 0;
    }
    if (lastWindowsPos == -1) {
        lastWindowsPos = 0;
    }
    if (lastExtensionPos == -1) {
        return -1;
    }
    if (lastUnixPos > lastWindowsPos) {
        return -1;
    }
    if (lastWindowsPos > lastExtensionPos) {
        return -1;
    }
    return lastExtensionPos;
}

