public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("Thread")) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot();
                threadSnapshot.setThreadName(line.substring(line.indexOf(":") + 1).trim());
                threadSnapshot.setThreadId(Integer.parseInt(line.substring(line.indexOf(":") + 1, line.indexOf(":") + 1 + 10).trim()));
                threadSnapshot.setThreadState(line.substring(line.indexOf(":") + 1 + 10, line.indexOf(":") + 1 + 10 + 10).trim());
                threadSnapshot.setThreadCpuTime(Long.parseLong(line.substring(line.indexOf(":") + 1 + 10 + 10, line.indexOf(":") + 1 + 10 + 10 + 10).trim()));
                threadSnapshot.setThreadUserTime(Long.parseLong(line.substring(line.indexOf(":") + 1 + 10 + 10 + 10, line.indexOf(":") + 1 + 10 + 10 + 10 + 10).trim()));
                threadSnapshot.setThreadBlockedTime(Long.parseLong(line.substring(line.indexOf(":") + 1 + 10 + 10 + 10 + 10, line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10).trim()));
                threadSnapshot.setThreadWaitedTime(Long.parseLong(line.substring(line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10, line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10 + 10).trim()));
                threadSnapshot.setThreadBlockedCount(Integer.parseInt(line.substring(line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10 + 10, line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10 + 10 + 10).trim()));
                threadSnapshot.setThreadWaitedCount(Integer.parseInt(line.substring(line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10 + 10 + 10, line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10 + 10 + 10 + 10).trim()));
                threadSnapshot.setThreadStackTrace(line.substring(line.indexOf(":") + 1 + 10 + 10 + 10 + 10 + 10 + 10 + 10 + 10, line.length()).trim());
                threadSnapshots.add(threadSnapshot);
            }
        }
    }
    return threadSnapshots;
}
